## SUBSCRIPTION MANAGER

### SubscriptionManager.swift

```swift
import SwiftUI
import StoreKit

@Observable
class SubscriptionManager {
    static let shared = SubscriptionManager()

    var products: [Product] = []
    var purchasedProductIDs: Set<String> = []
    var isLoading = false
    var errorMessage: String?

    // ⚠️ CHANGE THESE TO YOUR APP'S PRODUCT IDS
    private let productIDs = [
        "com.yourcompany.yourapp.pro.weekly",   // $0.29/week with 3-day trial
        "com.yourcompany.yourapp.pro.monthly"   // $0.99/month with 3-day trial
    ]

    var isPro: Bool { !purchasedProductIDs.isEmpty }

    // Convenience computed properties
    var weeklyProduct: Product? {
        products.first { $0.id.contains("weekly") }
    }

    var monthlyProduct: Product? {
        products.first { $0.id.contains("monthly") }
    }

    init() {
        Task { await loadProducts() }
        Task { await updatePurchasedProducts() }
        listenForTransactions()
    }

    @MainActor
    func loadProducts() async {
        isLoading = true
        errorMessage = nil
        do {
            products = try await Product.products(for: productIDs)
            // Sort: monthly first (featured), then weekly
            products.sort { p1, p2 in
                p1.id.contains("monthly") && !p2.id.contains("monthly")
            }
        } catch {
            errorMessage = "Failed to load products: \(error.localizedDescription)"
        }
        isLoading = false
    }

    func purchase(_ product: Product) async -> Bool {
        do {
            let result = try await product.purchase()
            switch result {
            case .success(let verification):
                let transaction = try checkVerified(verification)
                await transaction.finish()
                await updatePurchasedProducts()
                DS.Haptics.success()
                return true
            case .userCancelled, .pending:
                return false
            @unknown default:
                return false
            }
        } catch {
            errorMessage = "Purchase failed: \(error.localizedDescription)"
            DS.Haptics.error()
            return false
        }
    }

    func restorePurchases() async -> Bool {
        do {
            try await AppStore.sync()
            await updatePurchasedProducts()
            return !purchasedProductIDs.isEmpty
        } catch {
            errorMessage = "Restore failed: \(error.localizedDescription)"
            return false
        }
    }

    @MainActor
    private func updatePurchasedProducts() async {
        var purchased: Set<String> = []
        for await result in Transaction.currentEntitlements {
            if case .verified(let transaction) = result {
                if transaction.revocationDate == nil {
                    purchased.insert(transaction.productID)
                }
            }
        }
        purchasedProductIDs = purchased
    }

    private func checkVerified<T>(_ result: VerificationResult<T>) throws -> T {
        switch result {
        case .unverified(_, let error):
            throw error
        case .verified(let safe):
            return safe
        }
    }

    private func listenForTransactions() {
        Task.detached {
            for await result in Transaction.updates {
                if case .verified(let transaction) = result {
                    await transaction.finish()
                    await self.updatePurchasedProducts()
                }
            }
        }
    }

    // MARK: - Trial & Pricing Helpers (Dynamic from App Store)

    /// Check if user is eligible for free trial
    func isEligibleForTrial(_ product: Product) async -> Bool {
        guard let subscription = product.subscription else { return false }
        return await subscription.isEligibleForIntroOffer
    }

    /// Get trial period text (e.g., "3 days free")
    func trialPeriodText(_ product: Product) -> String? {
        guard let intro = product.subscription?.introductoryOffer,
              intro.paymentMode == .freeTrial else { return nil }
        let period = intro.period
        let value = period.value
        let unit = period.unit
        switch unit {
        case .day: return value == 1 ? "1 day free" : "\(value) days free"
        case .week: return value == 1 ? "1 week free" : "\(value) weeks free"
        case .month: return value == 1 ? "1 month free" : "\(value) months free"
        case .year: return value == 1 ? "1 year free" : "\(value) years free"
        @unknown default: return nil
        }
    }

    /// Get subscription period text (e.g., "per week", "per month")
    func periodText(_ product: Product) -> String {
        guard let period = product.subscription?.subscriptionPeriod else { return "" }
        switch period.unit {
        case .day: return period.value == 7 ? "per week" : "per day"
        case .week: return "per week"
        case .month: return "per month"
        case .year: return "per year"
        @unknown default: return ""
        }
    }
}
