struct SpaceBackground: View {
    @Environment(\.accessibilityReduceMotion) private var reduceMotion

    private let colors: [Color] = [
        .black.opacity(0.15), .blue.opacity(0.08), .black.opacity(0.15),
        .black.opacity(0.15), .purple.opacity(0.06), .black.opacity(0.15),
        .black.opacity(0.15), .blue.opacity(0.08), .black.opacity(0.15)
    ]

    var body: some View {
        ZStack {
            // Mesh gradient background
            MeshGradient(
                width: 3, height: 3,
                points: [
                    [0, 0], [0.5, 0], [1, 0],
                    [0, 0.5], [0.5, 0.5], [1, 0.5],
                    [0, 1], [0.5, 1], [1, 1]
                ],
                colors: colors
            )

            // Animated stars (respects reduce motion)
            if !reduceMotion {
                StarField()
            }
        }
        .ignoresSafeArea()
    }
}

struct StarField: View {
    @State private var twinkle = false

    var body: some View {
        Canvas { context, size in
            let stars = generateStars(in: size)
            for star in stars {
                let opacity = twinkle ? star.baseOpacity * 0.5 : star.baseOpacity
                context.fill(
                    Circle().path(in: CGRect(x: star.x, y: star.y, width: star.size, height: star.size)),
                    with: .color(.white.opacity(opacity))
                )
            }
        }
        .onAppear {
            withAnimation(.easeInOut(duration: 2).repeatForever(autoreverses: true)) {
                twinkle = true
            }
        }
    }

    private func generateStars(in size: CGSize) -> [Star] {
        var stars: [Star] = []
        let count = 30
        for i in 0..<count {
            let seed = Double(i * 7919)
            stars.append(Star(
                x: seed.truncatingRemainder(dividingBy: size.width),
                y: (seed * 1.3).truncatingRemainder(dividingBy: size.height),
                size: CGFloat(1 + (seed.truncatingRemainder(dividingBy: 2))),
                baseOpacity: 0.3 + (seed.truncatingRemainder(dividingBy: 0.5))
            ))
        }
        return stars
    }

    struct Star {
        let x: CGFloat
        let y: CGFloat
        let size: CGFloat
        let baseOpacity: Double
    }
}

